        user_score += 1
    else:
        print(f"Computer wins! You chose: {user_choice}. Score: {user_score} - {computer_score}")
        computer_score += 1

    return user_score, computer_score

def play_game():
    """Play multiple rounds of Rock, Paper, Scissors"""
